1346	// ---------------------------------------------------------------------------
1347	// 业务校验
1348	// ---------------------------------------------------------------------------
1349	
1350	function formatResourceIds(store: Store, ids: string[]): string {
1351	  return ids
1352	    .map((id) => {
1353	      const r = store.resources.find((x) => x.id === id);
1354	      return r ? `${id}（${r.name}）` : id;
1355	    })
1356	    .join('、');
1357	}
1358	
1359	// 校验请求中的资源标识：去重、检查存在性；返回按标识排序的集合
1360	function resolveResourceIds(store: Store, rawIds: string[]): string[] {
1361	  const problems: string[] = [];
1362	  const seen = new Set<string>();
1363	  const dupes: string[] = [];
1364	  for (const id of rawIds) {
1365	    if (seen.has(id)) {
1366	      if (!dupes.includes(id)) dupes.push(id);
1367	    }
1368	    seen.add(id);
1369	  }
1370	  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);
1371	
1372	  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
1373	  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);
1374	
1375	  if (problems.length > 0) throw new BizError(problems.join('\n'));
1376	  return [...seen].sort();
1377	}
1378	
1379	function openSegmentsOf(r: ResourceRec): Array<[number, number]> {
1380	  return mergeIntervals(
1381	    r.open.map(
1382	      ([s, e]) =>
1383	        [parseDateTime(s, '开放区间开始时间'), parseDateTime(e, '开放区间结束时间')] as [number, number],
1384	    ),
1385	  );
1386	}
1387	
1388	// 从连续区间中扣除一段停用（左闭右开），返回剩余连续区间
1389	function subtractSegments(
1390	  segments: Array<[number, number]>,
1391	  cuts: Array<[number, number]>,
1392	): Array<[number, number]> {
1393	  let result = segments;
1394	  for (const [cs, ce] of mergeIntervals(cuts)) {
1395	    const next: Array<[number, number]> = [];
1396	    for (const [s, e] of result) {
1397	      if (ce <= s || e <= cs) {
1398	        next.push([s, e]);
1399	        continue;
1400	      }
1401	      if (s < cs) next.push([s, cs]);
1402	      if (ce < e) next.push([ce, e]);
1403	    }
1404	    result = next;
1405	  }
1406	  return result;
1407	}
1408	
1409	// 某资源的有效停用记录（按开始时间、标识排序）
1410	function activeClosuresOf(store: Store, resourceId: string): ClosureRec[] {
1411	  return store.closures
1412	    .filter((c) => c.resourceId === resourceId && c.status === 'active')
1413	    .sort(
1414	      (a, b) =>
1415	        parseDateTime(a.start, '停用开始时间') - parseDateTime(b.start, '停用开始时间') ||
1416	        a.id.localeCompare(b.id),
1417	    );
1418	}
1419	
1420	// 实际可用时间：原开放区间合并后，扣除该资源全部有效停用区间的并集（原开放记录保留）
1421	function availableSegmentsOf(store: Store, r: ResourceRec): Array<[number, number]> {
1422	  const cuts = activeClosuresOf(store, r.id).map(
1423	    (c) =>
1424	      [parseDateTime(c.start, '停用开始时间'), parseDateTime(c.end, '停用结束时间')] as [number, number],
1425	  );
1426	  return subtractSegments(openSegmentsOf(r), cuts);
1427	}
1428	
1429	interface CoverageGap {
1430	  id: string;
1431	  r: ResourceRec;
1432	  closures: ClosureRec[]; // 与该区间重叠的相关有效停用（按开始时间、标识排序）
1433	}
1434	
1435	// 找出实际可用时间（开放扣除有效停用）不能完整覆盖 [startMin, endMin) 的资源
1436	function findCoverageGaps(
1437	  store: Store,
1438	  ids: string[],
1439	  startMin: number,
1440	  endMin: number,
1441	): CoverageGap[] {
1442	  const gaps: CoverageGap[] = [];
1443	  for (const id of ids) {
1444	    const r = store.resources.find((x) => x.id === id)!;
1445	    if (isFullyCovered(availableSegmentsOf(store, r), startMin, endMin)) continue;
1446	    const closures = activeClosuresOf(store, id).filter((c) => {
1447	      const cs = parseDateTime(c.start, '停用开始时间');
1448	      const ce = parseDateTime(c.end, '停用结束时间');
1449	      return cs < endMin && startMin < ce;
1450	    });
1451	    gaps.push({id, r, closures});
1452	  }
1453	  return gaps;
1454	}
1455	
1456	// 开放不足资源的统一展示：资源行 + 相关有效停用（标识与时间）
1457	function gapLines(gaps: CoverageGap[], indent: string): string[] {
1458	  const lines: string[] = [];
1459	  for (const g of gaps) {
1460	    lines.push(`${indent}- ${g.id}（${g.r.name}）`);
1461	    for (const c of g.closures) {
1462	      lines.push(`${indent}  相关有效停用: ${c.id}（${c.start} → ${c.end}）`);
1463	    }
1464	  }
1465	  return lines;
1466	}
1467	
1468	// 校验每个资源的实际可用时间都能完整覆盖 [startMin, endMin)
1469	function assertOpenCoverage(store: Store, ids: string[], startMin: number, endMin: number): void {
1470	  const failing = findCoverageGaps(store, ids, startMin, endMin);
1471	  if (failing.length > 0) {
1472	    throw new BizError(
1473	      '开放时间不足，以下资源的实际可用时间（开放区间扣除有效停用）不能完整覆盖预约区间：\n' +
1474	        gapLines(failing, '').join('\n'),
1475	    );
1476	  }
1477	}
1478	
1479	interface Conflict {
1480	  booking: BookingRec;
1481	  shared: string[];
1482	}
1483	
1484	// 与“已预约”记录求冲突：共同资源且时间重叠（左闭右开）；可排除自身
1485	function findConflicts(
1486	  store: Store,
1487	  ids: string[],
1488	  startMin: number,
1489	  endMin: number,
1490	  excludeBookingId?: string,
1491	): Conflict[] {
1492	  const wanted = new Set(ids);
1493	  const conflicts: Conflict[] = [];
1494	  for (const b of store.bookings) {
1495	    if (b.status !== 'active') continue;
1496	    if (excludeBookingId !== undefined && b.id === excludeBookingId) continue;
1497	    const bStart = parseDateTime(b.start, '预约开始时间');
1498	    const bEnd = parseDateTime(b.end, '预约结束时间');
1499	    const overlap = bStart < endMin && startMin < bEnd;
1500	    if (!overlap) continue;
1501	    const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
1502	    if (shared.length > 0) conflicts.push({booking: b, shared});
1503	  }
1504	  conflicts.sort((a, b) => a.booking.id.localeCompare(b.booking.id));
1505	  return conflicts;
1506	}
1507	
1508	function assertNoConflicts(conflicts: Conflict[], store: Store): void {
1509	  if (conflicts.length === 0) return;
1510	  const lines = conflicts.map(
1511	    (c) => `- ${c.booking.id}：共同资源 ${formatResourceIds(store, c.shared)}`,
1512	  );
1513	  throw new BizError(`预约与以下预约冲突（共同资源时间重叠）：\n${lines.join('\n')}`);
1514	}
1515	
1516	// ---------------------------------------------------------------------------
1517	// 多项预约目标的统一批次校验（无写入副作用）
1518	//
1519	// 创建系列、批量改期、安全撤销与 iCalendar 导入共用本套逻辑，不再各自重复
1520	// 整批可行性循环。校验针对“全部目标生效后”的安排，统一三类检查：
1521	//   1) 实际可用覆盖：开放区间重叠或相接合并后扣除有效停用并集，须连续覆盖目标；
1522	//   2) 批外占用：批外有效预约（已取消不占用）与目标的共同资源时间重叠；
1523	//   3) 批内冲突：本批各目标彼此之间的共同资源时间重叠。
1524	// 区间一律左闭右开，端点相接可行；仅共同资源重叠才算冲突。
1525	// 本函数只读取数据与目标，绝不修改目标、业务记录或标识计数；
1526	// 全部失败项一次性收集（批内冲突在双方各自的失败项中都出现），
1527	// 诊断的业务定位（成员时间/预约标识/UID）与报告顺序由各入口负责。
1528	// ---------------------------------------------------------------------------
1529	
1530	interface ValidationTarget {
1531	  startMin: number;
1532	  endMin: number;
1533	  resourceIds: string[]; // 已校验、按标识排序的完整目标资源集合
1534	}
1535	
1536	interface BatchTargetFailure {
1537	  index: number; // 目标数组下标（0 基）；报告顺序与业务定位由入口决定
1538	  gaps: CoverageGap[]; // 实际可用时间不能完整覆盖目标的资源及相关有效停用
1539	  external: Conflict[]; // 与批外有效预约的冲突（按预约标识排序）
1540	  internal: Array<{otherIndex: number; shared: string[]}>; // 批内冲突（双方互见）
1541	}
1542	
1543	// excludeBookingIds：本批涉及预约的标识，其当前占用不计入批外占用
1544	// （改期与撤销据此允许整批交换时段和资源；系列与导入传空集合）
1545	function validateBatchTargets(
1546	  store: Store,
1547	  targets: ReadonlyArray<ValidationTarget>,
1548	  excludeBookingIds: ReadonlySet<string> = new Set<string>(),
1549	): BatchTargetFailure[] {
1550	  const failures: BatchTargetFailure[] = [];
1551	  for (let i = 0; i < targets.length; i++) {
1552	    const t = targets[i];
1553	    const gaps = findCoverageGaps(store, t.resourceIds, t.startMin, t.endMin);
1554	    const external = findConflicts(store, t.resourceIds, t.startMin, t.endMin).filter(
1555	      (c) => !excludeBookingIds.has(c.booking.id),
1556	    );
1557	    const wanted = new Set(t.resourceIds);
1558	    const internal: BatchTargetFailure['internal'] = [];
1559	    for (let j = 0; j < targets.length; j++) {
1560	      if (j === i) continue;
1561	      const o = targets[j];
1562	      if (!(o.startMin < t.endMin && t.startMin < o.endMin)) continue;
1563	      const shared = o.resourceIds.filter((id) => wanted.has(id)).sort();
1564	      if (shared.length > 0) internal.push({otherIndex: j, shared});
1565	    }
1566	    if (gaps.length > 0 || external.length > 0 || internal.length > 0) {
1567	      failures.push({index: i, gaps, external, internal});
1568	    }
1569	  }
1570	  return failures;
1571	}
