1577	interface GlobalArgs {
1578	  dataFile: string;
1579	  help: boolean;
1580	  rest: string[];
1581	}
1582	
1583	function splitGlobalArgs(argv: string[]): GlobalArgs {
1584	  const result: GlobalArgs = {dataFile: DEFAULT_DATA_FILE, help: false, rest: []};
1585	  for (let i = 0; i < argv.length; i++) {
1586	    const a = argv[i];
1587	    if (a === '-h' || a === '--help') {
1588	      result.help = true;
1589	    } else if (a === '--data') {
1590	      const v = argv[++i];
1591	      if (v === undefined) throw new UsageError('选项 --data 缺少数据文件路径');
1592	      result.dataFile = v;
1593	    } else if (a.startsWith('--data=')) {
1594	      result.dataFile = a.slice('--data='.length);
1595	      if (result.dataFile === '') throw new UsageError('选项 --data 缺少数据文件路径');
1596	    } else {
1597	      result.rest.push(a);
1598	    }
1599	  }
1600	  return result;
