1608	// 子命令选项解析：allowed 中列出的选项均需带值；multi 中的选项可重复
1609	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
1610	  const allowedSet = new Set(allowed);
1611	  const multiSet = new Set(multi);
1612	  const values = new Map<string, string[]>();
1613	  const positionals: string[] = [];
1614	
1615	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
1616	    if (inline !== undefined) return [inline, index];
1617	    const v = args[index + 1];
1618	    if (v === undefined || v.startsWith('-')) {
1619	      throw new UsageError(`选项 --${key} 缺少值`);
1620	    }
1621	    return [v, index + 1];
1622	  };
1623	
1624	  for (let i = 0; i < args.length; i++) {
1625	    const a = args[i];
1626	    if (a.startsWith('--')) {
1627	      let key: string;
1628	      let inline: string | undefined;
1629	      const eq = a.indexOf('=');
1630	      if (eq >= 0) {
1631	        key = a.slice(2, eq);
1632	        inline = a.slice(eq + 1);
1633	      } else {
1634	        key = a.slice(2);
1635	      }
1636	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
1637	      let v: string;
1638	      [v, i] = takeValue(key, inline, i);
1639	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
1640	      if (!multiSet.has(key) && values.has(key)) {
1641	        throw new UsageError(`选项 --${key} 只能指定一次`);
1642	      }
1643	      const list = values.get(key) ?? [];
1644	      list.push(v);
1645	      values.set(key, list);
1646	    } else if (a.startsWith('-') && a !== '-') {
1647	      throw new UsageError(`未知参数: ${a}`);
1648	    } else {
1649	      positionals.push(a);
1650	    }
1651	  }
1652	  return {values, positionals};
1653	}
1654	
1655	function requireFlag(values: Map<string, string[]>, key: string): string {
1656	  const v = values.get(key)?.[0];
1657	  if (v === undefined) throw new UsageError(`缺少必需选项 --${key}`);
1658	  return v;
1659	}
