1760	  if (booking.status === 'cancelled') {
1761	    throw new BizError(`预约 ${id} 已取消，不能改期`);
1762	  }
1763	
1764	  const hasTime = values.has('start') || values.has('end');
1765	  const hasResource = values.has('resource');
1766	  if (!hasTime && !hasResource) {
1767	    throw new BizError('未指定任何改动：请提供 --start/--end 修改时间，或 --resource 替换资源（可同时提供）');
1768	  }
1769	
1770	  const startRaw = values.get('start')?.[0] ?? booking.start;
1771	  const endRaw = values.get('end')?.[0] ?? booking.end;
1772	  const startMin = parseDateTime(startRaw, '预约开始时间');
1773	  const endMin = parseDateTime(endRaw, '预约结束时间');
