1886	async function cmdRescheduleBatch(args: string[]): Promise<void> {
1887	  const {values, positionals} = parseFlags(args, []);
1888	  if (values.size > 0) {
1889	    throw new UsageError(
1890	      `reschedule-batch 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`,
1891	    );
1892	  }
1893	  if (positionals.length !== 1) {
1894	    throw new UsageError('用法: reschedule-batch <改期清单文件>');
1895	  }
1896	  const manifestFile = positionals[0];
1897	
1898	  const file = activeDataFile;
1899	  const store = await loadStoreForWrite(file);
1900	  const records = parseManifestShape(await loadManifest(manifestFile), manifestFile);
1901	
1902	  // 第一阶段：逐项做与业务数据相关的基础校验，收集全部问题后一次性拒绝整批
1903	  const problems: string[] = [];
1904	  const seenBooking = new Map<string, number>(); // 标识 -> 首次出现的序号（1 基）
1905	  const planned: Array<BatchTarget | null> = [];
1906	  records.forEach((rec, idx) => {
1907	    const at = `第 ${idx + 1} 项（${rec.bookingId as string}）`;
1908	    let ok = true;
1909	
1910	    const firstAt = seenBooking.get(rec.bookingId as string);
1911	    if (firstAt !== undefined) {
1912	      problems.push(`${at} 预约标识重复：该标识已在第 ${firstAt} 项出现，每项预约在清单中只能出现一次`);
1913	      ok = false;
1914	    } else {
1915	      seenBooking.set(rec.bookingId as string, idx + 1);
1916	    }
1917	
1918	    const booking = store.bookings.find((b) => b.id === rec.bookingId);
1919	    if (!booking) {
1920	      problems.push(`${at} 未知预约标识: ${rec.bookingId}`);
1921	      ok = false;
1922	    } else if (booking.status === 'cancelled') {
1923	      problems.push(`${at} 预约 ${booking.id} 已取消，不能改期`);
1924	      ok = false;
1925	    }
1926	
1927	    const rawRids = rec.resourceIds as string[];
1928	    const dupes = rawRids.filter((id, j) => rawRids.indexOf(id) !== j);
1929	    if (dupes.length > 0) problems.push(`${at} 资源重复指定: ${[...new Set(dupes)].join('、')}`);
1930	    const unknown = [...new Set(rawRids)]
1931	      .filter((id) => !store.resources.some((r) => r.id === id))
1932	      .sort();
1933	    if (unknown.length > 0) problems.push(`${at} 未知资源标识: ${unknown.join('、')}`);
1934	
1935	    let startMin = 0;
1936	    let endMin = 0;
1937	    let startParsed = false;
1938	    let endParsed = false;
1939	    try {
1940	      startMin = parseDateTime(rec.start as string, `${at} 目标开始时间`);
1941	      startParsed = true;
1942	    } catch (err) {
1943	      problems.push((err as BizError).message);
1944	    }
1945	    try {
1946	      endMin = parseDateTime(rec.end as string, `${at} 目标结束时间`);
1947	      endParsed = true;
1948	    } catch (err) {
1949	      problems.push((err as BizError).message);
1950	    }
1951	    if (startParsed && endParsed && endMin <= startMin) {
1952	      problems.push(
1953	        `${at} 目标结束时间必须晚于开始时间（开始: ${rec.start}，结束: ${rec.end}），允许跨日`,
1954	      );
1955	      ok = false;
1956	    }
1957	
1958	    if (!ok || !booking) {
1959	      planned.push(null);
1960	      return;
1961	    }
1962	    planned.push({
1963	      index: idx,
1964	      booking,
1965	      startRaw: rec.start as string,
1966	      endRaw: rec.end as string,
1967	      startMin,
1968	      endMin,
1969	      resourceIds: [...new Set(rawRids)].sort(),
1970	    });
1971	  });
1972	
1973	  if (problems.length > 0) {
1974	    throw new BizError(`改期清单 ${manifestFile} 校验失败，整批拒绝（原有安排保持不变）：\n${problems.map((p) => `- ${p}`).join('\n')}`);
1975	  }
1976	  const targets = planned as BatchTarget[];
1977	  const batchIds = new Set(targets.map((t) => t.booking.id));
1978	
1979	  // 第二阶段：对“整批完成后”的安排做统一批次校验（无写入副作用）。
1980	  // 本批预约的旧占用一律不视为障碍（排除本批全部标识）；
1981	  // 障碍只来自本批之外的有效预约，以及本批各项的目标安排彼此之间。
1982	  const failures = validateBatchTargets(store, targets, batchIds);
1983	
1984	  if (failures.length > 0) {
1985	    // 按清单顺序报告全部不满足条件的项；批内冲突在双方项中都会出现
1986	    const blocks = failures.map((f) => {
1987	      const t = targets[f.index];
1988	      const lines = [`第 ${t.index + 1} 项 ${t.booking.id} 目标 ${t.startRaw} → ${t.endRaw}：`];
1989	      if (f.gaps.length > 0) {
1990	        lines.push('  开放不足资源:');
