  if (!booking) throw new BizError(`未知预约标识: ${id}`);
  if (booking.status === 'cancelled') {
    // 幂等：再次取消成功且不做任何改动
    console.log(`预约 ${id} 已是取消状态，未做改动。`);
    return;

