3081	    for (const id of g.candidates) {
3082	      if (freeById.has(id)) continue;
3083	      const free = resourceFreeSegments(store, id, wStart, wEnd);
3084	      freeById.set(id, free);
3085	      for (const [s, e] of free) {
3086	        if (e - s >= duration) starts.add(s);
3087	      }
3088	    }
3089	  }
3090	
3091	  const usableAt = (s: number): ((id: string) => boolean) => {
