// ---------------------------------------------------------------------------
// 弹性批量改期（reschedule-flex）：尽量少改动既有预约的联合改期
//
// 读取本地 JSON 清单（{"items": [...]}，非空、有顺序），每项给出一个既有预约
// 标识、目标窗口与有顺序的候选资源组（每组列出一个可任选其一的候选资源数组），
// 时长保持预约当前长度。为整份清单求解同时可行的最终安排：排除本批旧占用，
// 其余有效预约按现状阻挡（取消记录与未兑现候补不阻挡）；开放区间重叠或相接
// 合并后扣除有效停用并集。各项完整落窗，每组恰选一个候选且所选互不相同，
// 全部所选资源同时连续可用、全程固定；仅共同资源的左闭右开时间重叠才冲突，
// 端点相接可行。
//
// 取舍：先最少化变化预约数量（起止时间或完整资源集合不同才算变化，资源顺序
// 不计）；数量相同再按清单顺序逐项先比开始分钟、再按组序比资源标识字符串，
// 取字典序最小的完整方案（候选书写顺序不影响结果）。求解按变化数预算 k 从 0
// 递增试探：候选开始分钟取“基础空闲段起点 ∪ 本项当前开始（完整落窗时）”与
// “其他项占用结束（s_j + d_j）”的闭包——最少变化的最小方案里，未变化项保持
// 当前开始，已变化项的开始若能再提前（空闲段起点）或被其他项占用结束顶住，
// 否则提前它不增加变化数却得到字典序更小方案，矛盾；故每个开始必在闭包内。
// 预算内按清单顺序深度优先（开始升序、同一开始的资源序列字典序升序），首个
// 完整方案即该预算下的最小方案；首个有解的 k 即最少变化数。
//
// 只改本批预约的时间与资源：标识、状态、系列归属、导入身份与首次请求、候补
// 原请求及兑现关联全部保留，不新建预约、不自动处理候补。至少一项有变化时，
// 全部提交项的前后完整安排、系列归属与清单顺序记为一条稳定不复用的批量改期
// 操作记录（O0001…），与改期同次原子保存，仅推进操作计数；可用 list-batch-ops
// 查询、undo-batch-op 整笔安全撤销（撤销后重提产生变化时分配新操作标识）。
// 全部保持现状即可行时成功但不写文件、不建记录、不推进计数；无解或任何失败
// 不落盘、不推进计数。
// ---------------------------------------------------------------------------

interface FlexRescheduleItem {
  index: number; // 1 基清单序号
  booking: BookingRec; // 目标预约（有效）
  startRaw: string; // 窗口开始（YYYY-MM-DDTHH:mm）
  endRaw: string; // 窗口结束
  startMin: number;
  endMin: number;
  duration: number; // 预约当前长度（分钟），改期后保持不变
  curStartMin: number; // 当前开始分钟
  curEndMin: number; // 当前结束分钟
  groups: RequirementGroup[]; // 有顺序的候选资源组，每组恰选一个候选
}

// 清单结构（与业务数据无关的纯类型校验）；返回逐项原始记录
function parseFlexRescheduleShape(raw: unknown, file: string): Array<Record<string, unknown>> {
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
    throw new BizError(`改期清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
  }
  const o = raw as Record<string, unknown>;
  for (const k of Object.keys(o)) {
    if (k !== 'items') throw new BizError(`改期清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
  }
  if (!Array.isArray(o.items)) {
    throw new BizError(`改期清单 ${file} 内容非法：items 必须是非空数组`);
  }
  const items = o.items as unknown[];
  if (items.length === 0) throw new BizError(`改期清单 ${file} 为空：items 至少包含一项改期请求`);

  const problems: string[] = [];
  const records: Array<Record<string, unknown> | null> = [];
  items.forEach((it, idx) => {
    const at = `第 ${idx + 1} 项`;
    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
      problems.push(`${at} 必须是对象`);
      records.push(null);
      return;
    }
    const rec = it as Record<string, unknown>;
    for (const k of Object.keys(rec)) {
      if (k !== 'bookingId' && k !== 'window' && k !== 'groups') {
        problems.push(`${at} 存在未知字段 “${k}”（只允许 bookingId、window、groups）`);
      }
    }
    if (typeof rec.bookingId !== 'string' || rec.bookingId === '') {
      problems.push(`${at} 的 bookingId 必须是非空字符串`);
    }
    if (typeof rec.window !== 'string' || rec.window === '') {
      problems.push(`${at} 的 window 必须是 窗口开始/窗口结束 形式的非空字符串`);
    }
    if (!Array.isArray(rec.groups) || rec.groups.length === 0) {
      problems.push(`${at} 的 groups 必须是非空数组（至少一个有顺序的候选资源组）`);
    } else {
      rec.groups.forEach((g, gi) => {
        if (!Array.isArray(g) || g.length === 0) {
          problems.push(`${at} 第 ${gi + 1} 候选资源组必须是非空数组（可任选其一的候选资源标识）`);
        } else {
          g.forEach((id) => {
            if (typeof id !== 'string' || id === '') {
              problems.push(`${at} 第 ${gi + 1} 候选资源组含非法候选：候选资源标识必须是非空字符串`);
            }
          });
        }
      });
    }
    records.push(rec);
  });
  if (problems.length > 0) {
    throw new BizError(`改期清单 ${file} 内容非法，整单拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
  }
  return records as Array<Record<string, unknown>>;
}

// 逐项做与业务数据相关的校验（预约存在且有效、清单内不重复，窗口真实有效且
// 长度不少于预约当前时长，组内重复与未知资源），收集全部问题后一次性拒绝整单
function parseFlexRescheduleItems(
  store: Store,
  records: Array<Record<string, unknown>>,
  file: string,
): FlexRescheduleItem[] {
  const problems: string[] = [];
  const seenBooking = new Map<string, number>(); // 标识 -> 首次出现的序号（1 基）
  const items: Array<FlexRescheduleItem | null> = records.map((rec, idx) => {
    const bookingId = rec.bookingId as string;
    const at = `第 ${idx + 1} 项（${bookingId}）`;
    let ok = true;

    const firstAt = seenBooking.get(bookingId);
    if (firstAt !== undefined) {
      problems.push(`${at} 预约标识重复：该标识已在第 ${firstAt} 项出现，每项预约在清单中只能出现一次`);
      ok = false;
    } else {
      seenBooking.set(bookingId, idx + 1);
    }

    const booking = store.bookings.find((b) => b.id === bookingId);
    if (!booking) {
      problems.push(`${at} 未知预约标识: ${bookingId}`);
      ok = false;
    } else if (booking.status === 'cancelled') {
      problems.push(`${at} 预约 ${bookingId} 已取消，不能改期`);
      ok = false;
    }

    let win: {start: string; end: string; startMin: number; endMin: number} | null = null;
    try {
      win = parseFlexWindow(rec.window as string, `${at}窗口`);
    } catch (err) {
      if (err instanceof BizError) {
        problems.push(err.message);
        ok = false;
      } else {
        throw err;
      }
    }

    const groups: RequirementGroup[] = [];
    (rec.groups as string[][]).forEach((ids, gi) => {
      const glabel = `${at} 第 ${gi + 1} 候选资源组`;
      const seen = new Set<string>();
      const dupes: string[] = [];
      for (const id of ids) {
        if (seen.has(id) && !dupes.includes(id)) dupes.push(id);
        seen.add(id);
      }
      if (dupes.length > 0) {
        problems.push(`${glabel}内候选资源重复: ${dupes.join('、')}`);
        ok = false;
      }
      const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
      if (unknown.length > 0) {
        problems.push(`${glabel}含未知资源标识: ${unknown.join('、')}`);
        ok = false;
      }
      groups.push({index: gi + 1, candidates: [...seen].sort()});
    });

    if (!ok || win === null || !booking) return null;
    const curStartMin = parseDateTime(booking.start, '预约开始时间');
    const curEndMin = parseDateTime(booking.end, '预约结束时间');
    const duration = curEndMin - curStartMin;
    if (win.endMin - win.startMin < duration) {
      problems.push(
        `${at} 窗口长度 ${win.endMin - win.startMin} 分钟小于预约当前时长 ${duration} 分钟` +
          `（窗口: ${win.start} → ${win.end}；时长保持预约当前长度）`,
      );
      return null;
    }
    return {
      index: idx + 1,
      booking,
      startRaw: win.start,
      endRaw: win.end,
      startMin: win.startMin,
      endMin: win.endMin,
      duration,
      curStartMin,
      curEndMin,
      groups,
    };
  });
  if (problems.length > 0) {
    throw new BizError(
      `改期清单 ${file} 校验失败，整单拒绝（原有安排保持不变）：\n${problems.map((p) => `- ${p}`).join('\n')}`,
    );
  }
  return items as FlexRescheduleItem[];
}

// 目标资源集合是否与预约当前资源集合相同（顺序不计；booking.resourceIds 已按标识排序）
function sameResourceSet(picks: string[], currentSorted: string[]): boolean {
  const sorted = [...picks].sort();
  return sorted.length === currentSorted.length && sorted.every((id, i) => id === currentSorted[i]);
}

// 联合求解“尽量少改动”的最终安排：返回按清单顺序的各项安排，无整体解返回 null。
// 按变化数预算 k 从 0 递增，预算内按清单顺序深度优先（开始升序、同一开始的
// 资源序列字典序升序），首个完整方案即“先最少变化、再逐项先比开始分钟、
// 再按组序比资源标识”的最小方案。
function solveFlexReschedule(
  store: Store,
  items: FlexRescheduleItem[],
  batchIds: ReadonlySet<string>,
): FlexPlacement[] | null {
  // 每项各候选资源的基础空闲段：实际可用时间（开放合并后扣除有效停用并集）
  // 裁进自身窗口，再扣除本批之外有效预约的占用（本批旧占用不计障碍；
  // 已取消预约/停用与未兑现候补不阻挡）
  const baseFree: Array<Map<string, Array<[number, number]>>> = items.map((it) => {
    const m = new Map<string, Array<[number, number]>>();
    for (const g of it.groups) {
      for (const id of g.candidates) {
        if (!m.has(id)) m.set(id, resourceFreeSegments(store, id, it.startMin, it.endMin, batchIds));
      }
    }
    return m;
  });

  // 候选开始分钟闭包：基础空闲段起点与本项当前开始（完整落窗时），
  // 加上“被其他项占用结束顶住”的起点 s_i = s_j + d_j
  // （仅候选资源集合有交集的项之间传播；值域有限，必收敛）
  const candidateIds = items.map((it) => {
    const set = new Set<string>();
    for (const g of it.groups) for (const id of g.candidates) set.add(id);
    return set;
  });
  const sharesCandidate = (a: number, b: number): boolean => {
    for (const id of candidateIds[a]) if (candidateIds[b].has(id)) return true;
    return false;
  };
  const candStarts: Array<Set<number>> = items.map((it, i) => {
    const set = new Set<number>();
    for (const segs of baseFree[i].values()) {
      for (const [s] of segs) {
        if (s + it.duration <= it.endMin) set.add(s);
      }
    }
    // 未变化项保持当前开始：当前安排完整落窗时，当前开始必是候选
    if (it.curStartMin >= it.startMin && it.curEndMin <= it.endMin) set.add(it.curStartMin);
    return set;
  });
  let changed = true;
  while (changed) {
    changed = false;
    for (let j = 0; j < items.length; j++) {
      for (let i = 0; i < items.length; i++) {
        if (i === j || !sharesCandidate(i, j)) continue;
        for (const s of candStarts[j]) {
          const t = s + items[j].duration;
          if (
            t >= items[i].startMin &&
            t + items[i].duration <= items[i].endMin &&
            !candStarts[i].has(t)
          ) {
            candStarts[i].add(t);
            changed = true;
          }
        }
      }
    }
  }

  const isUnchanged = (it: FlexRescheduleItem, s: number, picks: string[]): boolean =>
    s === it.curStartMin && sameResourceSet(picks, it.booking.resourceIds);

  // 已放置项对各资源的占用（随试探入栈/出栈增减）
  const occById = new Map<string, Array<[number, number]>>();

  const search = (idx: number, budget: number): FlexPlacement[] | null => {
    if (idx === items.length) return [];
    const it = items[idx];
    // 当前空闲段 = 基础空闲段扣除已放置项占用
    const freeById = new Map<string, Array<[number, number]>>();
    for (const [id, segs] of baseFree[idx]) {
      const occ = occById.get(id);
      freeById.set(id, occ !== undefined && occ.length > 0 ? subtractSegments(segs, occ) : segs);
    }
    for (const s of [...candStarts[idx]].sort((a, b) => a - b)) {
      const e = s + it.duration;
      const cache = new Map<string, boolean>();
      const usable = (id: string): boolean => {
        let v = cache.get(id);
        if (v === undefined) {
          v = isFullyCovered(freeById.get(id)!, s, e);
          cache.set(id, v);
        }
        return v;
      };
      for (const picks of assignmentsInLexOrder(it.groups, usable)) {
        const cost = isUnchanged(it, s, picks) ? 0 : 1;
        if (cost > budget) continue;
        for (const id of picks) {
          const occ = occById.get(id) ?? [];
          occ.push([s, e]);
          occById.set(id, occ);
        }
        const rest = search(idx + 1, budget - cost);
        if (rest !== null) return [{startMin: s, endMin: e, picks}, ...rest];
        for (const id of picks) occById.get(id)!.pop();
      }
    }
    return null;
  };

  // 变化数预算从 0 递增：首个有解的预算即最少变化预约数量
  for (let k = 0; k <= items.length; k++) {
    const plan = search(0, k);
    if (plan !== null) return plan;
  }
  return null;
}

async function cmdRescheduleFlex(args: string[]): Promise<void> {
  const {values, positionals} = parseFlags(args, []);
  if (values.size > 0) {
    throw new UsageError(
      `reschedule-flex 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`,
    );
  }
  if (positionals.length !== 1) {
    throw new UsageError('用法: reschedule-flex <改期清单文件>');
  }
  const manifestFile = positionals[0];

  // 修改入口：先取得写入保护再读最新数据，求解至保存全程受保护
  const file = activeDataFile;
  const store = await loadStoreForWrite(file);
  const records = parseFlexRescheduleShape(await loadManifest(manifestFile), manifestFile);
  const items = parseFlexRescheduleItems(store, records, manifestFile);
  const batchIds = new Set(items.map((it) => it.booking.id));

  const plan = solveFlexReschedule(store, items, batchIds);
  if (plan === null) {
    throw new BizError(
      `无整体解：清单 ${manifestFile} 的 ${items.length} 项预约不存在同时可行的最终安排` +
        '（每项须完整落在自身窗口内并保持当前时长，各组所选资源互不相同并全程固定，' +
        '本批旧占用不计障碍，其余有效预约按现状阻挡）。未改动任何预约，数据文件未改动。',
    );
  }

  // 各项最终安排（窗口已校验在 0001-9999 内，时段不超出窗口，格式化不会失败）
  const resolved = items.map((it, i) => {
    const p = plan[i];
    const start = formatDateTime(p.startMin);
    const end = formatDateTime(p.endMin);
    if (start === null || end === null) {
      // 理论不可达
      throw new BizError('可行时段超出四位年份范围');
    }
    return {start, end, picks: p.picks, changed: !isCurrentArrangement(it, p)};
  });
  const changedCount = resolved.filter((r) => r.changed).length;

  const renderItems = (): void => {
    items.forEach((it, i) => {
      const r = resolved[i];
      console.log(`第 ${i + 1} 项 ${it.booking.id}（${r.changed ? '已改期' : '保持不变'}）:`);
      if (it.booking.seriesId) console.log(`  所属系列: ${it.booking.seriesId}（保持不变）`);
      console.log(`  时间: ${r.start} → ${r.end}`);
      console.log('  资源（按需求组）:');
      r.picks.forEach((id, g) => {
        const res = store.resources.find((x) => x.id === id)!;
        console.log(`    第 ${g + 1} 组: ${id}（${res.name}，${RESOURCE_TYPE_LABEL[res.type]}）`);
      });
    });
  };

  if (changedCount === 0) {
    // 全部保持现状即可行：成功但不写文件、不建记录、不推进计数
    console.log(
      `弹性批量改期成功：共 ${items.length} 项，全部保持当前安排即可行（最少改动 0 项），无业务变化` +
        '（标识与系列归属不变，未生成改期操作记录，数据文件与标识计数未改动）',
    );
    renderItems();
    return;
  }

  // 至少一项有变化：全部提交项的前后完整安排、提交时系列归属与清单顺序记为
  // 一条“未撤销”操作记录，与新安排同一次原子保存；仅推进操作计数。
  // 仅改时间与资源；标识、status、seriesId、导入身份、候补关联及其余计数全部不变。
  const opItems: BatchOpItem[] = items.map((it, i) => {
    const item: BatchOpItem = {
      bookingId: it.booking.id,
      before: {
        start: it.booking.start,
        end: it.booking.end,
        resourceIds: [...it.booking.resourceIds],
      },
      after: {start: resolved[i].start, end: resolved[i].end, resourceIds: [...resolved[i].picks].sort()},
    };
    if (it.booking.seriesId !== undefined) item.seriesId = it.booking.seriesId;
    return item;
  });
  store.batchSeq += 1;
  const opId = `O${String(store.batchSeq).padStart(4, '0')}`;
  items.forEach((it, i) => {
    if (!resolved[i].changed) return;
    it.booking.start = resolved[i].start;
    it.booking.end = resolved[i].end;
    it.booking.resourceIds = [...resolved[i].picks].sort();
  });
  store.batchOps.push({id: opId, status: 'active', items: opItems});
  await saveStore(file, store);

  console.log(
    `弹性批量改期成功：操作标识 ${opId}，共 ${items.length} 项` +
      `（最少改动 ${changedCount} 项；标识与系列归属不变，未创建预约或系列）`,
  );
  renderItems();
  console.log(`本次改期已记录为 ${opId}：可用 list-batch-ops 查询，undo-batch-op ${opId} 整笔安全撤销。`);
}

// 该放置是否即预约当前安排（开始分钟相同且资源集合相同，资源顺序不计）
function isCurrentArrangement(it: FlexRescheduleItem, p: FlexPlacement): boolean {
  return p.startMin === it.curStartMin && sameResourceSet(p.picks, it.booking.resourceIds);
}

